cd "/c/Users/coneil/AppData/Local/Temp/claude/87995a179e8ca25a/62d1c137-a316-4c55-b30a-3f6dac53053e/scratchpad/research/early-nuclear-imaging" && cat > csearch.js <<'EOF'
// usage: node csearch.js "query" [limit]   or  node csearch.js --title "File:Name.jpg"
const {execFileSync}=require('child_process');
const strip=s=>(s||'').replace(/<[^>]+>/g,' ').replace(/&amp;/g,'&').replace(/&[a-z#0-9]+;/gi,' ').replace(/\s+/g,' ').trim();
const sleep=ms=>Atomics.wait(new Int32Array(new SharedArrayBuffer(4)),0,0,ms);
let url;
if(process.argv[2]=='--title'){url='https://commons.wikimedia.org/w/api.php?action=query&titles='+encodeURIComponent(process.argv[3])+'&prop=imageinfo&iiprop=url%7Cextmetadata%7Csize%7Cmime&iiurlwidth=1280&format=json';}
else{url='https://commons.wikimedia.org/w/api.php?action=query&generator=search&gsrsearch='+encodeURIComponent(process.argv[2])+'&gsrnamespace=6&gsrlimit='+(process.argv[3]||12)+'&prop=imageinfo&iiprop=url%7Cextmetadata%7Csize%7Cmime&iiurlwidth=1280&format=json';}
let j=null;
for(let t=0;t<6;t++){const out=execFileSync('curl',['-s','-A','petct-site-research/1.0',url],{encoding:'utf8',maxBuffer:1e8});
 try{j=JSON.parse(out);break}catch(e){sleep(8000*(t+1));}}
if(!j){console.log('RATE LIMITED');process.exit(0)}
if(!j.query||!j.query.pages){console.log('no results');process.exit(0)}
for(const p of Object.values(j.query.pages)){const i=(p.imageinfo||[])[0];if(!i){console.log(p.title,'(no imageinfo)');continue;}const e=i.extmetadata||{};
 if(process.argv[2]=='--title'){const o={title:p.title,url:i.url,thumburl:i.thumburl,descriptionurl:i.descriptionurl,width:i.width,height:i.height,mime:i.mime};for(const k of ['LicenseShortName','LicenseUrl','Artist','Credit','UsageTerms','AttributionRequired','DateTimeOriginal','ImageDescription','Copyrighted','Restrictions'])o[k]=strip(e[k]&&e[k].value).slice(0,500);console.log(JSON.stringify(o,null,1));}
 else console.log(p.title,'|',i.width+'x'+i.height,i.mime,'|',strip(e.LicenseShortName&&e.LicenseShortName.value),'|',strip(e.Artist&&e.Artist.value).slice(0,60),'|',strip(e.DateTimeOriginal&&e.DateTimeOriginal.value).slice(0,24),'|',strip(e.ImageDescription&&e.ImageDescription.value).slice(0,140));}
EOF
for q in "Hal Anger" "Anger scintillation camera" "Brownell positron"; do echo "== $q"; node csearch.js "$q"; sleep 4; done

